Brief:
A lighthouse with a few short floors: light every lamp on a floor before the tide reaches it, then climb the stairs to the next floor.

Plan:
{"gameType":"stage-clear","input":"tap-anywhere","lang":"en","loop":"Tap each lamp on the floor to light it before the rising tide reaches you, then climb the stairs to the next floor. Losing all floors before lighting every lamp ends the run; clearing the top floor wins.","slug":"lighthouse-tide","style":"chalkboard","title":"Lighthouse Tide"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="en">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Lighthouse Tide</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #2f3e3a; overflow: hidden;
11|     font-family: Georgia, 'Comic Sans MS', cursive, sans-serif;
12|   }
13|   canvas {
14|     display: block;
15|     touch-action: none;
16|   }
17| </style>
18| </head>
19| <body>
20| <canvas id="game"></canvas>
21| <script>
22| // ---- Bridge helper (verbatim) ----
23| const CARTRIDGE = {
24|   send(type, payload = {}) {
25|     window.parent.postMessage(
26|       { source: "cartridge", v: 1, type, payload },
27|       "*",
28|     );
29|   },
30| };
31| 
32| window.addEventListener("message", (event) => {
33|   const data = event.data;
34|   if (!data || data.source !== "cartridge-host") return;
35|   if (data.type === "pause") paused = true;
36|   if (data.type === "resume") paused = false;
37|   if (data.type === "reset") backToTitle();
38| });
39| 
40| // ---- Setup canvas ----
41| const canvas = document.getElementById("game");
42| const ctx = canvas.getContext("2d");
43| canvas.style.touchAction = "none";
44| 
45| let dpr = Math.max(1, window.devicePixelRatio || 1);
46| let W = 0, H = 0;
47| 
48| function resize() {
49|   W = window.innerWidth;
50|   H = window.innerHeight;
51|   dpr = Math.max(1, window.devicePixelRatio || 1);
52|   canvas.width = Math.floor(W * dpr);
53|   canvas.height = Math.floor(H * dpr);
54|   canvas.style.width = W + "px";
55|   canvas.style.height = H + "px";
56|   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
57| }
58| window.addEventListener("resize", resize);
59| resize();
60| 
61| // ---- Palette ----
62| const COL = {
63|   slate: "#2f3e3a",
64|   chalk: "#eeeae0",
65|   accent: "#f2c14e",
66|   second: "#8fc1e3",
67| };
68| 
69| // ---- Chalk drawing helpers ----
70| function chalkLine(x1, y1, x2, y2, width, color, alpha) {
71|   ctx.lineCap = "round";
72|   ctx.lineJoin = "round";
73|   const wob = 1.2;
74|   for (let pass = 0; pass < 2; pass++) {
75|     ctx.beginPath();
76|     const ox = (Math.random() - 0.5) * wob;
77|     const oy = (Math.random() - 0.5) * wob;
78|     ctx.moveTo(x1 + ox, y1 + oy);
79|     // slight midpoint wobble
80|     const mx = (x1 + x2) / 2 + (Math.random() - 0.5) * wob * 2;
81|     const my = (y1 + y2) / 2 + (Math.random() - 0.5) * wob * 2;
82|     ctx.quadraticCurveTo(mx, my, x2 + ox, y2 + oy);
83|     ctx.lineWidth = width;
84|     ctx.strokeStyle = color;
85|     ctx.globalAlpha = alpha * (pass === 0 ? 1 : 0.5);
86|     ctx.stroke();
87|   }
88|   ctx.globalAlpha = 1;
89| }
90| 
91| function chalkCircle(cx, cy, r, width, color, alpha) {
92|   ctx.lineCap = "round";
93|   for (let pass = 0; pass < 2; pass++) {
94|     ctx.beginPath();
95|     const segs = 24;
96|     for (let i = 0; i <= segs; i++) {
97|       const a = (i / segs) * Math.PI * 2;
98|       const wob = (Math.random() - 0.5) * 1.5;
99|       const px = cx + Math.cos(a) * (r + wob);
100|       const py = cy + Math.sin(a) * (r + wob);
101|       if (i === 0) ctx.moveTo(px, py);
102|       else ctx.lineTo(px, py);
103|     }
104|     ctx.lineWidth = width;
105|     ctx.strokeStyle = color;
106|     ctx.globalAlpha = alpha * (pass === 0 ? 1 : 0.5);
107|     ctx.stroke();
108|   }
109|   ctx.globalAlpha = 1;
110| }
111| 
112| function hatchRect(x, y, w, h, color, alpha, spacing) {
113|   ctx.strokeStyle = color;
114|   ctx.lineWidth = 2;
115|   ctx.globalAlpha = alpha;
116|   spacing = spacing || 8;
117|   for (let i = -h; i < w; i += spacing) {
118|     const x1 = x + i;
119|     const y1 = y;
120|     const x2 = x + i + h;
121|     const y2 = y + h;
122|     ctx.beginPath();
123|     ctx.moveTo(Math.max(x, x1), y1 + Math.max(0, x - x1));
124|     ctx.lineTo(Math.min(x + w, x2), y2 - Math.max(0, x2 - (x + w)));
125|     ctx.stroke();
126|   }
127|   ctx.globalAlpha = 1;
128| }
129| 
130| function chalkText(text, x, y, size, color, alpha, align) {
131|   ctx.font = `${size}px Georgia, serif`;
132|   ctx.textAlign = align || "center";
133|   ctx.textBaseline = "middle";
134|   ctx.fillStyle = color;
135|   ctx.globalAlpha = alpha === undefined ? 1 : alpha;
136|   ctx.fillText(text, x, y);
137|   ctx.globalAlpha = 1;
138| }
139| 
140| // ---- Smudge background layer ----
141| let smudges = [];
142| function initSmudges() {
143|   smudges = [];
144|   for (let i = 0; i < 5; i++) {
145|     smudges.push({
146|       x: Math.random() * W,
147|       y: Math.random() * H,
148|       r: 60 + Math.random() * 120,
149|     });
150|   }
151| }
152| 
153| function drawSmudges() {
154|   for (const s of smudges) {
155|     ctx.beginPath();
156|     ctx.ellipse(s.x, s.y, s.r, s.r * 0.6, 0, 0, Math.PI * 2);
157|     ctx.fillStyle = COL.chalk;
158|     ctx.globalAlpha = 0.03;
159|     ctx.fill();
160|     ctx.globalAlpha = 1;
161|   }
162| }
163| 
164| // ---- Game state ----
165| let paused = false;
166| let running = false; // true after first tap (play begins)
167| let gameOver = false;
168| let gameWon = false;
169| 
170| const STAGE_COUNT = 5;
171| let stage = 0;
172| let lamps = [];
173| let lampsLit = 0;
174| let tideY = 0;
175| let tideSpeed = 0;
176| let floorY = 0;
177| let stageStartTime = 0;
178| let graceMs = 2500;
179| let stairsReady = false;
180| let stairsX = 0, stairsY = 0, stairsW = 60, stairsH = 80;
181| let message = "";
182| let messageTimer = 0;
183| let score = 0;
184| 
185| function stageGoalCount(s) {
186|   return Math.min(3 + s, 8);
187| }
188| 
189| function buildStage(s) {
190|   lamps = [];
191|   lampsLit = 0;
192|   stairsReady = false;
193|   const count = stageGoalCount(s);
194|   const margin = 60;
195|   const usableW = W - margin * 2;
196|   for (let i = 0; i < count; i++) {
197|     lamps.push({
198|       x: margin + Math.random() * usableW,
199|       y: H * 0.25 + Math.random() * (H * 0.4),
200|       lit: false,
201|       r: 22,
202|       flicker: Math.random() * Math.PI * 2,
203|     });
204|   }
205|   floorY = H * 0.85;
206|   tideY = H + 40;
207|   tideSpeed = (0.12 + s * 0.05) * (H / 700);
208|   stageStartTime = performance.now();
209|   stairsX = W - 90;
210|   stairsY = H * 0.15;
211|   message = `Stage ${s}: Light ${count} lamps!`;
212|   messageTimer = 3000;
213| }
214| 
215| function enterStage(next) {
216|   stage = next;
217|   buildStage(stage);
218|   CARTRIDGE.send("level", { index: stage });
219| }
220| 
221| function onGoalMet() {
222|   if (stage === STAGE_COUNT) {
223|     gameWon = true;
224|     gameOver = true;
225|     CARTRIDGE.send("end", { reason: "win", value: score });
226|   } else {
227|     score += 100;
228|     CARTRIDGE.send("score", { value: score });
229|     enterStage(stage + 1);
230|   }
231| }
232| 
233| function onStageFailed() {
234|   gameOver = true;
235|   gameWon = false;
236|   CARTRIDGE.send("end", { reason: "lose", value: score });
237| }
238| 
239| function backToTitle() {
240|   running = false;
241|   gameOver = false;
242|   gameWon = false;
243|   paused = false;
244|   stage = 0;
245|   score = 0;
246|   lamps = [];
247|   message = "";
248| }
249| 
250| // ---- Input ----
251| let lastTapTime = 0;
252| 
253| canvas.addEventListener("pointerdown", (event) => {
254|   event.preventDefault();
255|   if (paused) return;
256| 
257|   if (!running) {
258|     running = true;
259|     gameOver = false;
260|     gameWon = false;
261|     score = 0;
262|     CARTRIDGE.send("start");
263|     enterStage(1);
264|     return;
265|   }
266| 
267|   if (gameOver) {
268|     // tap to restart from title
269|     backToTitle();
270|     return;
271|   }
272| 
273|   const rect = canvas.getBoundingClientRect();
274|   const x = event.clientX - rect.left;
275|   const y = event.clientY - rect.top;
276| 
277|   // check stairs tap if all lamps lit
278|   if (stairsReady) {
279|     if (
280|       x > stairsX - 10 &&
281|       x < stairsX + stairsW + 10 &&
282|       y > stairsY - 10 &&
283|       y < stairsY + stairsH + 10
284|     ) {
285|       onGoalMet();
286|       return;
287|     }
288|   }
289| 
290|   // check lamp taps
291|   for (const lamp of lamps) {
292|     if (lamp.lit) continue;
293|     const dx = x - lamp.x;
294|     const dy = y - lamp.y;
295|     if (Math.sqrt(dx * dx + dy * dy) < Math.max(lamp.r, 22)) {
296|       lamp.lit = true;
297|       lampsLit++;
298|       score += 10;
299|       CARTRIDGE.send("score", { value: score });
300|       if (lampsLit >= lamps.length) {
301|         stairsReady = true;
302|         message = "All lit! Climb the stairs!";
303|         messageTimer = 2500;
304|       }
305|       break;
306|     }
307|   }
308| });
309| 
310| // ---- Draw functions ----
311| function drawTitle() {
312|   ctx.clearRect(0, 0, W, H);
313|   drawSmudges();
314|   drawLighthouseIcon(W / 2, H * 0.35, 70);
315| 
316|   chalkText("Lighthouse Tide", W / 2, H * 0.55, Math.min(42, W * 0.08), COL.chalk, 1);
317|   chalkText(
318|     "Light every lamp before the tide rises,",
319|     W / 2,
320|     H * 0.62,
321|     Math.min(20, W * 0.045),
322|     COL.chalk,
323|     0.85
324|   );
325|   chalkText(
326|     "then climb the stairs to the next floor.",
327|     W / 2,
328|     H * 0.67,
329|     Math.min(20, W * 0.045),
330|     COL.chalk,
331|     0.85
332|   );
333| 
334|   const pulse = 0.5 + 0.5 * Math.sin(performance.now() / 300);
335|   chalkText(
336|     "Tap to begin",
337|     W / 2,
338|     H * 0.8,
339|     Math.min(26, W * 0.06),
340|     COL.accent,
341|     0.6 + pulse * 0.4
342|   );
343| }
344| 
345| function drawLighthouseIcon(cx, cy, size) {
346|   // simple tower with hatching
347|   const w = size * 0.5;
348|   const h = size * 1.4;
349|   chalkLine(cx - w / 2, cy + h / 2, cx - w / 3, cy - h / 2, 4, COL.chalk, 0.8);
350|   chalkLine(cx + w / 2, cy + h / 2, cx + w / 3, cy - h / 2, 4, COL.chalk, 0.8);
351|   chalkLine(cx - w / 3, cy - h / 2, cx + w / 3, cy - h / 2, 4, COL.chalk, 0.8);
352|   chalkLine(cx - w / 2, cy + h / 2, cx + w / 2, cy + h / 2, 4, COL.chalk, 0.8);
353|   // lamp room
354|   chalkCircle(cx, cy - h / 2 - 14, 16, 3, COL.accent, 0.9);
355|   // rays
356|   for (let i = -2; i <= 2; i++) {
357|     chalkLine(
358|       cx,
359|       cy - h / 2 - 14,
360|       cx + i * 30,
361|       cy - h / 2 - 14 - 40,
362|       2,
363|       COL.accent,
364|       0.3
365|     );
366|   }
367| }
368| 
369| function drawLamp(lamp) {
370|   lamp.flicker += 0.08;
371|   const glow = lamp.lit ? 0.9 : 0.35 + Math.sin(lamp.flicker) * 0.15;
372|   const color = lamp.lit ? COL.accent : COL.second;
373|   chalkCircle(lamp.x, lamp.y, lamp.r, 3, color, glow);
374|   chalkCircle(lamp.x, lamp.y, lamp.r * 0.5, 2, color, glow * 0.7);
375|   if (lamp.lit) {
376|     for (let i = 0; i < 6; i++) {
377|       const a = (i / 6) * Math.PI * 2 + lamp.flicker * 0.3;
378|       const rr = lamp.r + 10;
379|       chalkLine(
380|         lamp.x + Math.cos(a) * lamp.r,
381|         lamp.y + Math.sin(a) * lamp.r,
382|         lamp.x + Math.cos(a) * rr,
383|         lamp.y + Math.sin(a) * rr,
384|         2,
385|         COL.accent,
386|         0.4
387|       );
388|     }
389|   }
390| }
391| 
392| function drawStairs() {
393|   const color = stairsReady ? COL.accent : COL.chalk;
394|   const alpha = stairsReady ? 0.9 : 0.35;
395|   for (let i = 0; i < 5; i++) {
396|     const sy = stairsY + (i * stairsH) / 5;
397|     chalkLine(
398|       stairsX,
399|       sy,
400|       stairsX + stairsW,
401|       sy,
402|       3,
403|       color,
404|       alpha
405|     );
406|   }
407|   chalkLine(stairsX, stairsY, stairsX, stairsY + stairsH, 3, color, alpha);
408|   chalkLine(
409|     stairsX + stairsW,
410|     stairsY,
411|     stairsX + stairsW,
412|     stairsY + stairsH,
413|     3,
414|     color,
415|     alpha
416|   );
417|   chalkText(
418|     stairsReady ? "GO!" : "",
419|     stairsX + stairsW / 2,
420|     stairsY - 20,
421|     18,
422|     COL.accent,
423|     0.9
424|   );
425| }
426| 
427| function drawTide() {
428|   const waveH = 10;
429|   ctx.beginPath();
430|   ctx.moveTo(0, tideY);
431|   for (let x = 0; x <= W; x += 20) {
432|     const y = tideY + Math.sin(x * 0.02 + performance.now() / 300) * waveH;
433|     ctx.lineTo(x, y);
434|   }
435|   ctx.lineTo(W, H);
436|   ctx.lineTo(0, H);
437|   ctx.closePath();
438|   ctx.fillStyle = COL.second;
439|   ctx.globalAlpha = 0.15;
440|   ctx.fill();
441|   ctx.globalAlpha = 1;
442| 
443|   // wave line chalk stroke
444|   for (let x = 0; x < W; x += 40) {
445|     const y1 = tideY + Math.sin(x * 0.02 + performance.now() / 300) * waveH;
446|     const y2 =
447|       tideY + Math.sin((x + 40) * 0.02 + performance.now() / 300) * waveH;
448|     chalkLine(x, y1, x + 40, y2, 3, COL.second, 0.6);
449|   }
450| }
451| 
452| function drawFloorLine() {
453|   for (let x = 0; x < W; x += 50) {
454|     chalkLine(x, floorY, x + 50, floorY, 3, COL.chalk, 0.3);
455|   }
456| }
457| 
458| function drawHUD() {
459|   chalkText(
460|     `Stage ${stage} / ${STAGE_COUNT}`,
461|     70,
462|     30,
463|     18,
464|     COL.chalk,
465|     0.8,
466|     "left"
467|   );
468|   chalkText(
469|     `Lamps: ${lampsLit}/${lamps.length}`,
470|     70,
471|     56,
472|     16,
473|     COL.accent,
474|     0.8,
475|     "left"
476|   );
477|   chalkText(`Score: ${score}`, W - 70, 30, 16, COL.chalk, 0.8, "right");
478| 
479|   if (messageTimer > 0) {
480|     chalkText(
481|       message,
482|       W / 2,
483|       H * 0.12,
484|       Math.min(24, W * 0.05),
485|       COL.accent,
486|       Math.min(1, messageTimer / 500)
487|     );
488|   }
489| }
490| 
491| function drawPauseOverlay() {
492|   ctx.fillStyle = COL.slate;
493|   ctx.globalAlpha = 0.6;
494|   ctx.fillRect(0, 0, W, H);
495|   ctx.globalAlpha = 1;
496|   chalkText("Paused", W / 2, H / 2, 32, COL.chalk, 1);
497| }
498| 
499| function drawGameOver() {
500|   ctx.clearRect(0, 0, W, H);
501|   drawSmudges();
502|   if (gameWon) {
503|     drawLighthouseIcon(W / 2, H * 0.3, 80);
504|     chalkText(
505|       "You lit every floor!",
506|       W / 2,
507|       H * 0.55,
508|       Math.min(36, W * 0.08),
509|       COL.accent,
510|       1
511|     );
512|   } else {
513|     chalkText(
514|       "The tide took the tower...",
515|       W / 2,
516|       H * 0.45,
517|       Math.min(30, W * 0.06),
518|       COL.chalk,
519|       0.9
520|     );
521|   }
522|   chalkText(
523|     `Final Score: ${score}`,
524|     W / 2,
525|     H * 0.6,
526|     Math.min(22, W * 0.05),
527|     COL.chalk,
528|     0.8
529|   );
530|   const pulse = 0.5 + 0.5 * Math.sin(performance.now() / 300);
531|   chalkText(
532|     "Tap to return to title",
533|     W / 2,
534|     H * 0.75,
535|     Math.min(22, W * 0.05),
536|     COL.second,
537|     0.5 + pulse * 0.4
538|   );
539| }
540| 
541| // ---- Main loop ----
542| let lastTime = performance.now();
543| 
544| function update(dt) {
545|   if (!running || paused || gameOver) return;
546| 
547|   const elapsed = performance.now() - stageStartTime;
548|   if (elapsed > graceMs) {
549|     tideY -= tideSpeed * dt;
550|   }
551| 
552|   if (messageTimer > 0) messageTimer -= dt;
553| 
554|   if (tideY <= floorY) {
555|     onStageFailed();
556|   }
557| }
558| 
559| function draw() {
560|   ctx.clearRect(0, 0, W, H);
561|   drawSmudges();
562| 
563|   if (!running) {
564|     drawTitle();
565|     requestAnimationFrame(loop);
566|     return;
567|   }
568| 
569|   if (gameOver) {
570|     drawGameOver();
571|     requestAnimationFrame(loop);
572|     return;
573|   }
574| 
575|   // background lighthouse silhouette
576|   drawLighthouseIcon(W / 2, H * 0.12, 40);
577| 
578|   drawFloorLine();
579|   for (const lamp of lamps) drawLamp(lamp);
580|   drawStairs();
581|   drawTide();
582|   drawHUD();
583| 
584|   if (paused) drawPauseOverlay();
585| 
586|   requestAnimationFrame(loop);
587| }
588| 
589| function loop(now) {
590|   const dt = Math.min(50, now - lastTime);
591|   lastTime = now;
592|   update(dt);
593|   draw();
594| }
595| 
596| // ---- Boot ----
597| initSmudges();
598| window.addEventListener("resize", initSmudges);
599| 
600| CARTRIDGE.send("boot", { title: "Lighthouse Tide", gameType: "stage-clear", lang: "en" });
601| 
602| requestAnimationFrame((t) => {
603|   lastTime = t;
604|   requestAnimationFrame(loop);
605| });
606| </script>
607| </body>
608| </html>
609|

